const save = (key, value) => localStorage.setItem(key, JSON.stringify(value));
save("bashcrawl-web-hero-v1", { name: "Mira", role: "wanderer", tourDone: true });
save("bashcrawl-web-shell-v1", { mode: "reference", onboarded: true, introSeen: true });
localStorage.setItem("bashcrawl-web-theme", "dark");
"seeded"

(async () => {
  // Switch to the other door (no reload), then sample its header for
  // 2.4 s: a door clip animates from its first frame, then stops.
  const door = location.hash.includes("arcade") ? "reference" : "arcade";
  location.hash = `#/${door}`;
  const tick = () => new Promise((done) => setTimeout(done, 20));
  let node = null;
  for (let i = 0; i < 100 && !node; i += 1) {
    await tick();
    node = document.querySelector(`[data-art="door-${door}"]`);
  }
  if (!node) throw new Error(`no door-${door} art after switching to #/${door}`);
  const frames = new Set();
  const until = Date.now() + 2400;
  while (Date.now() < until) {
    frames.add(node.textContent);
    await tick();
  }
  const playing = window.BashcrawlAmbient.isPlaying(node);
  if (frames.size < 3) throw new Error(`door-${door} painted ${frames.size} frame(s), expected an animation`);
  if (playing) throw new Error(`door-${door} still plays after 2.4 s; a door clip plays once`);
  return {
    art: node.dataset.art,
    distinctFrames: frames.size,
    ariaHidden: node.getAttribute("aria-hidden"),
    rest: node.textContent.split("\n").map((line) => line.trimEnd()),
  };
})()

